/**
 * Measured benchmark results shipped with the page. `results.json` is generated by
 * `bun scripts/build-results.ts` from the raw per-game records in `bench-results/`;
 * nothing in it is typed in by hand.
 */
import data from "./results.json";

export interface MatchupRow {
  readonly id: string;
  readonly label: string;
  readonly detail: string;
  readonly games: number;
  readonly wins: number;
  readonly losses: number;
  readonly draws: number;
  readonly winRate: number;
  readonly low: number;
  readonly high: number;
  readonly attackPerPiece: number;
  readonly rivalAttackPerPiece: number;
  readonly linesPerGame: number;
  readonly rivalLinesPerGame: number;
}

/** [seed, bot seat (0 = left, 1 = right), result (1 win, 0 loss, 2 draw/cap), ticks, bot sent, Hoiko sent] */
export type GameRow = readonly [number, 0 | 1, 0 | 1 | 2, number, number, number];

export interface Results {
  readonly generatedAt: string;
  readonly commit: string;
  readonly seeds: string;
  readonly headline: MatchupRow;
  readonly tagline: string;
  readonly copy: {
    readonly claim: string;
    readonly profiles: readonly string[];
    readonly fairness: readonly string[];
    readonly unmeasured: readonly string[];
  };
  readonly rows: readonly MatchupRow[];
  readonly games: readonly GameRow[];
  readonly rulesAudit: { readonly locks: number; readonly agree: number };
}

export const RESULTS = data as unknown as Results;
